export const getHpTestIntegrationUrl = () => {




  return `/api/hp/settings/test-integration`
}

/**
 * @summary Send a test notification via a configured integration
 */
export const hpTestIntegration = async (hpIntegrationTestInput: HpIntegrationTestInput, options?: RequestInit): Promise<HpIntegrationTestResult> => {

  return customFetch<HpIntegrationTestResult>(getHpTestIntegrationUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      hpIntegrationTestInput,)
  }
);}




export const getHpTestIntegrationMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof hpTestIntegration>>, TError,{data: BodyType<HpIntegrationTestInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof hpTestIntegration>>, TError,{data: BodyType<HpIntegrationTestInput>}, TContext> => {

const mutationKey = ['hpTestIntegration'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof hpTestIntegration>>, {data: BodyType<HpIntegrationTestInput>}> = (props) => {
          const {data} = props ?? {};

          return  hpTestIntegration(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type HpTestIntegrationMutationResult = NonNullable<Awaited<ReturnType<typeof hpTestIntegration>>>
    export type HpTestIntegrationMutationBody = BodyType<HpIntegrationTestInput>
    export type HpTestIntegrationMutationError = ErrorType<unknown>

    /**
 * @summary Send a test notification via a configured integration
 */
export const useHpTestIntegration = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof hpTestIntegration>>, TError,{data: BodyType<HpIntegrationTestInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof hpTestIntegration>>,
        TError,
        {data: BodyType<HpIntegrationTestInput>},
        TContext
      > => {
      return useMutation(getHpTestIntegrationMutationOptions(options));
    }

